import assert from 'node:assert/strict';
import {test} from 'node:test';
import {taskLabel} from '../src/labels.ts';

test('completed task has [x] prefix', () => {
  assert.equal(taskLabel('draft', true), '[x] draft');
});

test('incomplete task has [ ] prefix', () => {
  assert.equal(taskLabel('review', false), '[ ] review');
});

test('preserves the supplied name exactly', () => {
  assert.equal(taskLabel('  spaced item  ', true), '[x]   spaced item  ');
  assert.equal(taskLabel('', true), '[x] ');
  assert.equal(taskLabel('', false), '[ ] ');
  assert.equal(taskLabel('task [with] brackets: #1', true), '[x] task [with] brackets: #1');
});

